import{_ as t,o as e,c as o,ag as r}from"./chunks/framework.CAXxHpAX.js";const q=JSON.parse('{"title":"柔弱","description":"","frontmatter":{},"headers":[],"relativePath":"50-概念资料/dict-柔弱.md","filePath":"50-概念资料/dict-柔弱.md","lastUpdated":1778155802000}'),l={name:"50-概念资料/dict-柔弱.md"};function d(i,a,h,n,c,u){return e(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="柔弱" tabindex="-1">柔弱 <a class="header-anchor" href="#柔弱" aria-label="Permalink to &quot;柔弱&quot;">​</a></h1><blockquote><p>传统：道家 | 佛家对应：忍辱 | 儒家对应：谦让</p></blockquote><h2 id="了空居士的定义" tabindex="-1">了空居士的定义 <a class="header-anchor" href="#了空居士的定义" aria-label="Permalink to &quot;了空居士的定义&quot;">​</a></h2><p>&quot;柔弱&quot;不是软弱无能，而是<strong>潜移默化的持久力量</strong>。水滴石穿——水是最柔的，但能穿透最硬的石头。</p><p>了空居士说：柔弱胜刚强是一种<strong>策略智慧</strong>——不是硬碰硬的对抗，而是以柔克刚、以退为进。在处世中表现为：不争锋芒、不炫耀、不硬来。在家庭中：先软下来的那个人，才是真正有力量的人。</p><h2 id="原话出处" tabindex="-1">原话出处 <a class="header-anchor" href="#原话出处" aria-label="Permalink to &quot;原话出处&quot;">​</a></h2><blockquote><p>&quot;天下之至柔，驰骋天下之至坚。水是最柔的，但滴水可以穿石。&quot; — <a href="/60-原文段落/道德经43章-柔弱胜刚强">道德经43章-柔弱胜刚强</a></p></blockquote><blockquote><p>&quot;知其雄，守其雌——知道自己的力量，但要保持谦卑。不是软弱，是真正的强者之态。&quot;</p></blockquote><h2 id="常见误解" tabindex="-1">常见误解 <a class="header-anchor" href="#常见误解" aria-label="Permalink to &quot;常见误解&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误解</th><th>正解</th></tr></thead><tbody><tr><td>柔弱就是任人欺负</td><td>柔弱是以退为进的策略，不是永远被动挨打</td></tr><tr><td>柔弱不适用于职场</td><td>智慧布施——该报警就报警，忍不是目的，是看清形势后最佳选择</td></tr></tbody></table><h2 id="相关概念" tabindex="-1">相关概念 <a class="header-anchor" href="#相关概念" aria-label="Permalink to &quot;相关概念&quot;">​</a></h2><ul><li><a href="/50-概念资料/dict-和光同尘">dict-和光同尘</a> — 柔弱的外在表现：收敛锋芒，融入环境</li><li><a href="/50-概念资料/dict-无为">dict-无为</a> — 柔弱是无为在处世中的体现</li></ul><h2 id="相关模型" tabindex="-1">相关模型 <a class="header-anchor" href="#相关模型" aria-label="Permalink to &quot;相关模型&quot;">​</a></h2><ul><li><a href="/10-核心模型/model-圆融中和">model-圆融中和</a> — 柔弱是达成中道的一种方式</li><li><a href="/10-核心模型/model-对境不住">model-对境不住</a> — 不被挑衅带走，不硬碰硬地反应</li></ul><h2 id="修行实践" tabindex="-1">修行实践 <a class="header-anchor" href="#修行实践" aria-label="Permalink to &quot;修行实践&quot;">​</a></h2><p>遇到冲突时，不急着&quot;赢&quot;，先退一步看看全局。柔不是弱，是以最佳方式达到目的。在家里，先软下来的人真正有力量。</p>',16)])])}const b=t(l,[["render",d]]);export{q as __pageData,b as default};
